  'All bookings are subject to temple rules and availability.': 'అన్ని బుకింగ్‌లు ఆలయ నియమాలు మరియు అందుబాటుకు లోబడి ఉంటాయి.',
  'All payments are subject to temple rules and availability.': 'అన్ని చెల్లింపులు ఆలయ నియమాలు మరియు అందుబాటుకు లోబడి ఉంటాయి.',
  'All transactions are linked to this devotee profile. Click on each tab to view detailed history.': 'అన్ని లావాదేవీలు ఈ భక్తుని ప్రొఫైల్‌కు లింక్ చేయబడ్డాయి. వివరణాత్మక చరిత్రను చూడటానికి ప్రతి ట్యాబ్‌పై క్లిక్ చేయండి.',
  'Cash and Sponsorship categories do not require unit and quantity. They are recorded by amount only.': 'నగదు మరియు ప్రాయోజకత్వ వర్గాలకు యూనిట్ మరియు పరిమాణం అవసరం లేదు. అవి మొత్తం ద్వారా మాత్రమే నమోదు చేయబడతాయి.',
  'Changes in module access will be applied for users the next time they login.': 'మాడ్యూల్ యాక్సెస్‌లో మార్పులు వినియోగదారులు తదుపరిసారి లాగిన్ అయినప్పుడు వర్తిస్తాయి.',
  'Changes will be applied to the system settings.': 'మార్పులు సిస్టమ్ సెట్టింగ్‌లకు వర్తిస్తాయి.',
  'Choose a report and click Generate Report.': 'ఒక నివేదికను ఎంచుకుని నివేదిక రూపొందించండి క్లిక్ చేయండి.',
  'Fields below will change based on the category type selected.': 'ఎంచుకున్న వర్గం రకాన్ని బట్టి క్రింది ఫీల్డ్‌లు మారతాయి.',
  'Festival poojas are automatically scheduled for their festival window from the Festival Master.': 'పండుగ పూజలు పండుగల మాస్టర్ నుండి వాటి పండుగ కాలానికి స్వయంచాలకంగా షెడ్యూల్ చేయబడతాయి.',
  'If payment mode is UPI / QR Code, please enter the UTR / Transaction ID.': 'చెల్లింపు విధానం UPI / క్యూఆర్ కోడ్ అయితే, దయచేసి UTR / లావాదేవీ ఐడిని నమోదు చేయండి.',
  'Module access for this user. Defaults follow the selected role — customise as needed.': 'ఈ వినియోగదారు కోసం మాడ్యూల్ యాక్సెస్. డిఫాల్ట్‌లు ఎంచుకున్న పాత్రను అనుసరిస్తాయి — అవసరమైన విధంగా అనుకూలీకరించండి.',
  'Only plans configured for the selected pooja are shown below.': 'ఎంచుకున్న పూజ కోసం కాన్ఫిగర్ చేసిన ప్లాన్‌లు మాత్రమే క్రింద చూపబడ్డాయి.',
  'Please verify all details before proceeding to payment.': 'చెల్లింపుకు వెళ్లే ముందు దయచేసి అన్ని వివరాలను ధృవీకరించండి.',
  'Selecting a Pooja will load only the plans configured in Pooja Master.': 'ఒక పూజను ఎంచుకుంటే పూజ మాస్టర్‌లో కాన్ఫిగర్ చేసిన ప్లాన్‌లు మాత్రమే లోడ్ అవుతాయి.',
  'Awaiting committee decision on pricing.': 'ధర నిర్ణయం కోసం కమిటీ నిర్ణయం వేచి ఉంది.',
  'Select the pooja timing slot for the booking.': 'బుకింగ్ కోసం పూజ సమయ స్లాట్‌ను ఎంచుకోండి.',
  'Set once by the committee in the Festival Master — no manual entry needed.': 'పండుగల మాస్టర్‌లో కమిటీ ద్వారా ఒకసారి సెట్ చేయబడింది — మాన్యువల్ ఎంట్రీ అవసరం లేదు.',
  'Tax exemption is applicable only for Medical Donations.': 'పన్ను మినహాయింపు వైద్య విరాళాలకు మాత్రమే వర్తిస్తుంది.',
  'The role is created with no module access. Select it and toggle modules, then Save Changes.': 'పాత్ర మాడ్యూల్ యాక్సెస్ లేకుండా సృష్టించబడింది. దాన్ని ఎంచుకుని మాడ్యూల్‌లను టోగుల్ చేసి, ఆపై మార్పులు సేవ్ చేయండి.',
  'This pooja has no fixed fee — enter the committee\'s amount to continue.': 'ఈ పూజకు స్థిర రుసుము లేదు — కొనసాగించడానికి కమిటీ మొత్తాన్ని నమోదు చేయండి.',
  'User will receive login credentials on their registered email.': 'వినియోగదారు వారి నమోదిత ఇమెయిల్‌లో లాగిన్ ఆధారాలను అందుకుంటారు.',
  'You can complete the full profile later from Devotee Management.': 'మీరు తర్వాత భక్తుల నిర్వహణ నుండి పూర్తి ప్రొఫైల్‌ను పూర్తి చేయవచ్చు.',
  'Your pooja booking has been confirmed successfully. Thank you for your devotion.': 'మీ పూజ బుకింగ్ విజయవంతంగా నిర్ధారించబడింది. మీ భక్తికి ధన్యవాదాలు.',
  'Payment has been received successfully.': 'చెల్లింపు విజయవంతంగా అందుకోబడింది.',
  'Open a future day to prepare — performing is only possible for today': 'సిద్ధం కావడానికి భవిష్యత్ రోజును తెరవండి — నిర్వహణ నేటికి మాత్రమే సాధ్యం',
  'Optionally assign a poojari to perform this booking.': 'ఈ బుకింగ్‌ను నిర్వహించడానికి ఐచ్ఛికంగా పూజారిని కేటాయించండి.',
