  'Configure and manage temple poojas, available plans, rates, and validity': 'ఆలయ పూజలు, అందుబాటులో ఉన్న ప్లాన్‌లు, రేట్లు మరియు చెల్లుబాటును కాన్ఫిగర్ చేసి నిర్వహించండి',
