  'No backups yet. Click “Create Backup” to take a snapshot.': 'ఇంకా బ్యాకప్‌లు లేవు. స్నాప్‌షాట్ తీసుకోవడానికి “బ్యాకప్ సృష్టించండి” క్లిక్ చేయండి.',
