  'Note: All amounts shown are for the selected date range. Change the date range to view data for a different period.': 'గమనిక: చూపిన అన్ని మొత్తాలు ఎంచుకున్న తేదీ పరిధికి సంబంధించినవి. వేరే కాలానికి డేటాను చూడటానికి తేదీ పరిధిని మార్చండి.',
