  'Roles': 'పాత్రలు',
  'Schedule a pooja for a chosen date, time slot and poojari. For walk-up billing use Counter Billing.': 'ఎంచుకున్న తేదీ, సమయ స్లాట్ మరియు పూజారి కోసం పూజను షెడ్యూల్ చేయండి. వాక్-అప్ బిల్లింగ్ కోసం కౌంటర్ బిల్లింగ్ ఉపయోగించండి.',
