  'Your message has reached the temple office. Our staff will get back to you during temple hours.': 'మీ సందేశం ఆలయ కార్యాలయానికి చేరింది. మా సిబ్బంది ఆలయ సమయాల్లో మిమ్మల్ని సంప్రదిస్తారు.',
