  'Apply': 'వర్తింపజేయి',
  'All time slots for this date are over. The booking will be saved without a time slot.': 'ఈ తేదీకి అన్ని సమయ స్లాట్‌లు ముగిశాయి. బుకింగ్ సమయ స్లాట్ లేకుండా సేవ్ అవుతుంది.',
  'Booking a ceremony for a future date (Namakaranam, Annaprasana…)? Use': 'భవిష్యత్ తేదీకి ఒక కార్యక్రమాన్ని బుక్ చేస్తున్నారా (నామకరణం, అన్నప్రాసన…)? వాడండి',
  'Two-Factor Authentication will be requested after successful login (if enabled for your account).': 'విజయవంతమైన లాగిన్ తర్వాత టూ-ఫ్యాక్టర్ ప్రమాణీకరణ అడగబడుతుంది (మీ ఖాతాకు ప్రారంభించబడి ఉంటే).',
  'Category classifies the pooja type. Plans define how the pooja can be booked (e.g., Daily, Monthly, One-Time, Life Long).': 'వర్గం పూజ రకాన్ని వర్గీకరిస్తుంది. పూజను ఎలా బుక్ చేయవచ్చో ప్లాన్‌లు నిర్వచిస్తాయి (ఉదా. రోజువారీ, నెలవారీ, ఒకసారి, జీవితకాలం).',
  'Daily': 'రోజువారీ',
  'Monthly': 'నెలవారీ',
