  'Pay by cash or UPI — an official receipt is issued.': 'నగదు లేదా UPI ద్వారా చెల్లించండి — అధికారిక రసీదు జారీ చేయబడుతుంది.',
  'Annadanam Served': 'అన్నదానం అందించబడింది',
  'Food is offered to devotees on your chosen day.': 'మీరు ఎంచుకున్న రోజున భక్తులకు ఆహారం అందించబడుతుంది.',
  'Plates Served': 'అందించిన ప్లేట్లు',
  'Through devotee sponsorships': 'భక్తుల ప్రాయోజకత్వాల ద్వారా',
  'Recorded at the temple': 'ఆలయంలో నమోదు చేయబడింది',
  'Plates This Month': 'ఈ నెల ప్లేట్లు',
