  'Parking is available at the temple premises. Thursdays and festival days are busiest.': 'ఆలయ ఆవరణలో పార్కింగ్ అందుబాటులో ఉంది. గురువారాలు మరియు పండుగ రోజులు అత్యంత రద్దీగా ఉంటాయి.',
  'Support the daily needs and maintenance of the temple.': 'ఆలయ రోజువారీ అవసరాలు మరియు నిర్వహణకు మద్దతు ఇవ్వండి.',
  'Help provide charitable medical services.': 'ధార్మిక వైద్య సేవలను అందించడంలో సహాయపడండి.',
  'Contribute towards free meals for devotees.': 'భక్తులకు ఉచిత భోజనం కోసం సహకరించండి.',
  'Support temple renovation and expansion.': 'ఆలయ పునరుద్ధరణ మరియు విస్తరణకు మద్దతు ఇవ్వండి.',
  'Create a permanent fund for temple activities.': 'ఆలయ కార్యకలాపాల కోసం శాశ్వత నిధిని ఏర్పాటు చేయండి.',
