  'Rule: Purnima Vrat (Madhyahna) — the day Purnima begins if it begins before the end of Madhyahna (3rd fifth of sunrise→sunset); otherwise the next sunrise Purnima day.': 'నియమం: పౌర్ణమి వ్రతం (మధ్యాహ్నం) — మధ్యాహ్నం (సూర్యోదయం→సూర్యాస్తమయంలో 3వ ఐదవ భాగం) ముగిసేలోపు పౌర్ణమి ప్రారంభమైతే ఆ రోజు; లేకుంటే తదుపరి సూర్యోదయ పౌర్ణమి రోజు.',
