  'Select a confirmed Pournami date for': 'దీనికి నిర్ధారిత పౌర్ణమి తేదీని ఎంచుకోండి:',
  'Select a confirmed Pournami date for this pooja.': 'ఈ పూజకు నిర్ధారిత పౌర్ణమి తేదీని ఎంచుకోండి.',
  'Some full moons could not be resolved:': 'కొన్ని పౌర్ణములను నిర్ధారించలేకపోయాం:',
  'Source: Prokerala Panchang for': 'మూలం: Prokerala పంచాంగం —',
  'Sunrise / Sunset': 'సూర్యోదయం / సూర్యాస్తమయం',
  'superseded date(s) will be retired (kept for audit).': 'భర్తీ చేయబడిన తేదీ(లు) విరమించబడతాయి (ఆడిట్ కోసం ఉంచబడతాయి).',
  'Sync failed — confirmed dates were not changed.': 'సింక్ విఫలమైంది — నిర్ధారిత తేదీలు మార్చబడలేదు.',
  'Sync Pournami Dates': 'పౌర్ణమి తేదీలను సింక్ చేయండి',
  'They will no longer be able to sign in.': 'వారు ఇకపై సైన్ ఇన్ చేయలేరు.',
  'This cannot be undone. Poojas with bookings must be marked Inactive instead.': 'దీనిని రద్దు చేయలేరు. బుకింగ్‌లు ఉన్న పూజలను బదులుగా నిష్క్రియంగా గుర్తించాలి.',
  'This is a computer-generated receipt': 'ఇది కంప్యూటర్ ద్వారా రూపొందించిన రసీదు',
  'This receipt is valid only for the date and service mentioned.': 'ఈ రసీదు పేర్కొన్న తేదీ మరియు సేవకు మాత్రమే చెల్లుతుంది.',
  'This will allow new transactions for this date. Only reopen if corrections are needed.': 'ఇది ఈ తేదీకి కొత్త లావాదేవీలను అనుమతిస్తుంది. సవరణలు అవసరమైతే మాత్రమే తిరిగి తెరవండి.',
  'This will delete all existing categories and create standard temple donation categories. This action cannot be undone.': 'ఇది ఇప్పటికే ఉన్న అన్ని వర్గాలను తొలగించి ప్రామాణిక ఆలయ విరాళ వర్గాలను సృష్టిస్తుంది. ఈ చర్యను రద్దు చేయలేరు.',
  'Transaction reference is required for UPI payments.': 'UPI చెల్లింపులకు లావాదేవీ రిఫరెన్స్ తప్పనిసరి.',
