  'Valuables stored in custody.': 'విలువైన వస్తువులు భద్రపరచబడ్డాయి.',
  'Verification failed. Please try again.': 'ధృవీకరణ విఫలమైంది. దయచేసి మళ్ళీ ప్రయత్నించండి.',
