  // ── Server error messages (shown via api/client.js) ──
  'Invalid request. Please check your input and try again.': 'చెల్లని అభ్యర్థన. దయచేసి మీ వివరాలను తనిఖీ చేసి మళ్ళీ ప్రయత్నించండి.',
  'Your session has expired. Please log in again.': 'మీ సెషన్ ముగిసింది. దయచేసి మళ్ళీ లాగిన్ అవ్వండి.',
  'You do not have permission to perform this action.': 'ఈ చర్యను చేయడానికి మీకు అనుమతి లేదు.',
  'The requested resource was not found.': 'అభ్యర్థించిన సమాచారం కనుగొనబడలేదు.',
  'Request timed out. Please try again.': 'అభ్యర్థన సమయం ముగిసింది. దయచేసి మళ్ళీ ప్రయత్నించండి.',
  'This operation conflicts with existing data.': 'ఈ చర్య ఇప్పటికే ఉన్న డేటాతో విరుద్ధంగా ఉంది.',
  'Invalid data provided. Please check your input.': 'చెల్లని డేటా ఇవ్వబడింది. దయచేసి మీ వివరాలను తనిఖీ చేయండి.',
  'Too many requests. Please wait a moment and try again.': 'చాలా అభ్యర్థనలు వచ్చాయి. దయచేసి కొంతసేపు ఆగి మళ్ళీ ప్రయత్నించండి.',
  'Server error. Our team has been notified.': 'సర్వర్ లోపం. మా బృందానికి తెలియజేయబడింది.',
  'Server temporarily unavailable. Please try again shortly.': 'సర్వర్ తాత్కాలికంగా అందుబాటులో లేదు. దయచేసి కొద్దిసేపట్లో మళ్ళీ ప్రయత్నించండి.',
  'Service temporarily unavailable. Please try again shortly.': 'సేవ తాత్కాలికంగా అందుబాటులో లేదు. దయచేసి కొద్దిసేపట్లో మళ్ళీ ప్రయత్నించండి.',
  'Server timeout. Please try again.': 'సర్వర్ సమయం ముగిసింది. దయచేసి మళ్ళీ ప్రయత్నించండి.',
  '2FA is not enabled for this user': 'ఈ వినియోగదారుకు 2FA ప్రారంభించబడలేదు',
