  // ── Server messages (fixed text) ──
  'upcoming only supports Pournami and Amavasya': 'రాబోయే తేదీలు పౌర్ణమి మరియు అమావాస్యకు మాత్రమే అందుబాటులో ఉన్నాయి',
  'This material has recorded sales and cannot be renamed. Add a new material and mark this one Inactive instead.':
    'ఈ పదార్థానికి అమ్మకాలు నమోదై ఉన్నందున పేరు మార్చలేరు. కొత్త పదార్థాన్ని జోడించి, దీన్ని నిష్క్రియంగా గుర్తించండి.',
  'Prokerala API not configured. Set PROKERALA_CLIENT_ID and PROKERALA_CLIENT_SECRET environment variables.':
    'Prokerala API కాన్ఫిగర్ చేయబడలేదు. PROKERALA_CLIENT_ID మరియు PROKERALA_CLIENT_SECRET ఎన్విరాన్‌మెంట్ వేరియబుల్స్‌ను సెట్ చేయండి.',
  'Prokerala API not configured. Set PROKERALA_CLIENT_ID and PROKERALA_CLIENT_SECRET.':
    'Prokerala API కాన్ఫిగర్ చేయబడలేదు. PROKERALA_CLIENT_ID మరియు PROKERALA_CLIENT_SECRET ను సెట్ చేయండి.',
  'Unable to fetch Panchang data from Prokerala API. Please try again later.': 'Prokerala API నుండి పంచాంగ సమాచారం పొందలేకపోయాము. దయచేసి తర్వాత మళ్ళీ ప్రయత్నించండి.',
  'Unable to fetch calendar data from Prokerala API. Please try again later.': 'Prokerala API నుండి క్యాలెండర్ సమాచారం పొందలేకపోయాము. దయచేసి తర్వాత మళ్ళీ ప్రయత్నించండి.',
  "Unable to fetch today's data from Prokerala API. Please try again later.": 'Prokerala API నుండి ఈ రోజు సమాచారం పొందలేకపోయాము. దయచేసి తర్వాత మళ్ళీ ప్రయత్నించండి.',
  "'to' must be on or after 'from'.": 'ముగింపు తేదీ ప్రారంభ తేదీకి సమానంగా లేదా తర్వాత ఉండాలి.',
  'Ask for at most three years at a time.': 'ఒకేసారి గరిష్ఠంగా మూడు సంవత్సరాలు మాత్రమే అడగండి.',
  'Unknown festival': 'తెలియని పండుగ', 'Almanac day not found': 'పంచాంగ దినం కనుగొనబడలేదు',
