  'Backup is encrypted but BACKUP_ENCRYPTION_KEY not configured': 'బ్యాకప్ ఎన్‌క్రిప్ట్ చేయబడింది కానీ BACKUP_ENCRYPTION_KEY కాన్ఫిగర్ చేయబడలేదు',
