  'Food sponsorship details with person count.': 'వ్యక్తుల సంఖ్యతో అన్నదాన స్పాన్సర్‌షిప్ వివరాలు.',
  'Hundi collections deposited into the bank.': 'బ్యాంకులో జమ చేసిన హుండీ వసూళ్లు.',
